INSERT IGNORE INTO `Post` (`id`,`category`,`title`,`body`,`published`,`authorName`,`createdAt`,`updatedAt`) VALUES
('seed-post-1','RECRUIT','2026 집수리 교실 1기 수강생 모집','우리 동네 집은 우리 손으로! 기초 수리 기술을 배우는 집수리 교실 1기 수강생을 모집합니다.\n\n· 대상: 대전 유성구 거주 주민 누구나\n· 기간: 2026년 8월, 주 2회 총 8회\n· 내용: 공구 사용법, 방충망·수전·조명 교체, 안전 교육\n· 수료 후 마을관리사업단 활동 연계\n\n참여를 원하시면 아래 버튼으로 신청해 주세요.',1,'CHM Group','2026-07-01 09:00:00','2026-07-01 09:00:00'),
('seed-post-2','NOTICE','예비사회적기업 지정 신청 접수 완료','CHM Group이 2026년 7월 예비사회적기업 지정 신청을 완료했습니다.\n\n3년간의 리빙랩 실증 경험을 바탕으로, 2027년 인증 사회적기업 전환을 목표로 나아갑니다. 응원해 주신 주민과 파트너 기관에 감사드립니다.',1,'CHM Group','2026-06-24 09:00:00','2026-06-24 09:00:00'),
('seed-post-3','EVENT','어은동 리빙랩 성과공유회 개최 안내','지난 3년간 어은동·궁동에서 진행한 주민 참여형 주거관리 리빙랩의 성과를 나누는 자리를 마련했습니다.\n\n주민 수요조사 결과, 집수리 교육-서비스 연계 사례, 앞으로의 계획을 공유합니다. 관심 있는 주민과 기관 누구나 환영합니다.',1,'CHM Group','2026-06-12 09:00:00','2026-06-12 09:00:00'),
('seed-post-4','CAMPAIGN','장마철 대비 우리집 안전점검 캠페인','장마가 오기 전, 누수·곰팡이·전기 안전을 미리 점검하세요.\n\n캠페인 기간 중 신청 가구를 대상으로 기본 안전점검을 진행합니다. 점검 항목: 지붕·창호 누수, 배수, 콘센트·누전차단기, 곰팡이 취약부.',1,'CHM Group','2026-05-30 09:00:00','2026-05-30 09:00:00');
